CREATE TABLE IF NOT EXISTS gis_phase369_boundary_candidates (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id TEXT NOT NULL UNIQUE, provider TEXT NOT NULL, source_url TEXT, hierarchy_level TEXT NOT NULL, feature_count BIGINT, state_count BIGINT, geometry_valid_count BIGINT, evidence_score DOUBLE PRECISION NOT NULL DEFAULT 0, selection_status TEXT NOT NULL DEFAULT 'CANDIDATE', evidence JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE TABLE IF NOT EXISTS gis_phase369_resolution_gate (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), certification_version TEXT NOT NULL, gate_status TEXT NOT NULL, selected_candidate_id TEXT, lga_ward_assertions_enabled BOOLEAN NOT NULL DEFAULT false, evidence JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());